// penrose truchet 彭罗斯

//#define X(a,b)   cross(a,b).z
#define C(a,b,c) cross(a.xyz-d.xyz,b.xyz-d.xyz).z*cross(c.xyz-d.xyz,b.xyz-d.xyz).z>0.

vec4 hash(float p)
{
	vec4 p4 = fract(vec4(p) * vec4(.1031, .1030, .0973, .1099));
    p4 += dot(p4, p4.wzxy+33.33);
    return fract((p4.xxyz+p4.yzzw)*p4.zywx);

}

float L(vec2 a, vec2 b, vec2 p){
        b-=a; p-=a;
        return length(p - b * clamp(dot(p,b)/dot(b,b), 0., 1.));
}


void mainImage(out vec4 O, vec2 U)
{
        O = vec4(.8);//.7
        vec3 R = iResolution,u,uu;
        u.xy = 1.1*(U+U - R.xy)/ R.y; u.x += R.x/R.y*.8;
        u.y=-u.y;

        vec4 a,b,c,d,e,aa,bb,cc;
        c.y = 1.; b=-c; a.x = tan(6.28/5.);
        float i,T,tt, h,g=sqrt(5.)*.5-.5,k = a.x   ;

        float col, ccl,cs;

        bool ht = iMouse.x<iResolution.x*.55;


        for(i=0.;i<7.;i++){
                d.xy = a.xy + (b.xy-a.xy)*g;

                aa=a,bb=b;cc=c;

                if(T>.5){
                        col=1.-col;
                        // col+=mod(i,2.)*2.-1.;
                        if(C(a,c,u)) {
                                b=c,c=d, T--;
                                if(ht)col++;
                        }else{  
                                a=b,b=c,c=d;
                        }
                }else{        
                        e.xy = c.xy +(a.xy-c.xy)*g;

                        if(C(a,e,u)){
                                b=d,c=e, T++;    
                                if(ht)col--;
                        }else if( C(b,c,u)){
                                a=c, c=b, b=d;

                        }else{
                                a=c, b=d, c=e;

                        }


                }


        }



        float clr ;

        if(T>.5){
                //h = L(a.xy,b.xy,u.xy), 
                i = length(u-c.xyz)/length(a.xyz-c.xyz)-g*g;
                clr = a.w;
        }else{
                //h = L(a.xy,c.xy,u.xy), 
                i = length(u-b.xyz)/ length(c.xyz-b.xyz)-g;
                clr = a.w;

        }

        //h = min(h, L(b.xy,c.xy,u.xy));

        O += smoothstep( .05, 0., .3*L(bb.xy,cc.xy,u.xy)/length(bb-cc));


        // h dist line
        // i dist curve

        O -=   smoothstep( .35, .006, abs(i))
            *vec4(.0+hash(col + /*floor(iTime)/100.*/ 11.5 ))//*.9)
            // 62, 82,142,150,162

            ;
}
